using System; using System.Data; using System.IO; using System.Security.Cryptography; using System.Text; using System.Text.RegularExpressions;
namespace UCSPyayStudentRegistration.Helpers {
 public static class ValidationHelper { public static bool Email(string s){return Regex.IsMatch(s??"",@"^[^@\s]+@[^@\s]+\.[^@\s]+$");} public static bool MyanmarPhone(string s){return Regex.IsMatch((s??"").Replace(" ",""),@"^(\+?95|0)(9\d{7,9}|[1-8]\d{6,8})$");} public static bool Required(string s){return !string.IsNullOrWhiteSpace(s);} }
 public static class PasswordHelper { public static string Hash(string password,string salt){using(var d=new Rfc2898DeriveBytes(password,Convert.FromBase64String(salt),10000)){return Convert.ToBase64String(d.GetBytes(32));}} public static string NewSalt(){var b=new byte[16];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return Convert.ToBase64String(b);} public static bool Verify(string p,string s,string h){return Hash(p,s)==h;} }
 public static class FileHelper { public const long MaxBytes=5*1024*1024; public static bool Allowed(string p,bool document){var e=Path.GetExtension(p).ToLowerInvariant();return (e==".jpg"||e==".jpeg"||e==".png"||(document&&e==".pdf"))&&new FileInfo(p).Length<=MaxBytes;} public static string CopyUpload(string path,string category){var dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Uploads",category);Directory.CreateDirectory(dir);var target=Path.Combine(dir,Guid.NewGuid().ToString("N")+Path.GetExtension(path).ToLowerInvariant());File.Copy(path,target,true);return target;} }
 public static class ExcelExportHelper { public static void ExportCsv(DataTable t,string path){using(var w=new StreamWriter(path,false,Encoding.UTF8)){for(int c=0;c<t.Columns.Count;c++){if(c>0)w.Write(',');w.Write(Escape(t.Columns[c].ColumnName));}w.WriteLine();foreach(DataRow r in t.Rows){for(int c=0;c<t.Columns.Count;c++){if(c>0)w.Write(',');w.Write(Escape(Convert.ToString(r[c])));}w.WriteLine();}}} static string Escape(string s){return "\""+(s??"").Replace("\"","\"\"")+"\"";} }
}
